<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$reports=['revenue'=>['invoiced'=>(float)$db->query("SELECT COALESCE(SUM(total),0) FROM invoices WHERE status<>'cancelled'")->fetchColumn(),'paid'=>(float)$db->query("SELECT COALESCE(SUM(amount_paid),0) FROM invoices WHERE status<>'cancelled'")->fetchColumn(),'outstanding'=>(float)$db->query("SELECT COALESCE(SUM(balance_due),0) FROM invoices WHERE status IN ('sent','partially_paid','overdue')")->fetchColumn(),'successful_payments'=>(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM invoice_payments WHERE status='successful'")->fetchColumn()],'sales'=>['leads'=>(int)$db->query('SELECT COUNT(*) FROM leads')->fetchColumn(),'won'=>(int)$db->query("SELECT COUNT(*) FROM leads WHERE status='won'")->fetchColumn(),'pipeline'=>(float)$db->query("SELECT COALESCE(SUM(estimated_value),0) FROM leads WHERE status IN ('new','contacted','proposal')")->fetchColumn(),'proposals_accepted'=>(int)$db->query("SELECT COUNT(*) FROM proposals WHERE status='accepted'")->fetchColumn()],'operations'=>['active_projects'=>(int)$db->query("SELECT COUNT(*) FROM client_projects WHERE status IN ('planning','in_progress','in_review')")->fetchColumn(),'overdue_projects'=>(int)$db->query("SELECT COUNT(*) FROM client_projects WHERE due_date IS NOT NULL AND due_date<CURDATE() AND status NOT IN ('completed','cancelled')")->fetchColumn(),'open_tasks'=>(int)$db->query("SELECT COUNT(*) FROM project_tasks WHERE status NOT IN ('completed','cancelled')")->fetchColumn(),'open_tickets'=>(int)$db->query("SELECT COUNT(*) FROM support_tickets WHERE status NOT IN ('resolved','closed')")->fetchColumn()]];foreach($reports as $type=>$payload){$q=$db->prepare("INSERT INTO bi_report_runs(report_type,filters,status,completed_at) VALUES(?,?,?,NOW())");$q->execute([$type,json_encode(['generated_at'=>gmdate('c'),'metrics'=>$payload]),'completed']);}echo 'Phase 14 report snapshots completed at '.date('c').PHP_EOL;